// gelu_tanh(a) = a * sigmoid(2u) = a / (1 + 2^t), t = -2*sqrt(2/pi)*log2(e) * (a + 0.044715 a^3).
// One MUFU per element (ex2); the reciprocal is an integer-seed estimate refined by one cubic
// (Halley) and one Newton FMA step (rel. error < 1e-6), so no MUFU.RCP.
// Load policy by size: up to EF_MAX_ROWS rows the input loads carry L2::evict_first.
#include <cuda_runtime.h>
#include <stdint.h>

