               : "memory");
}

__device__ __forceinline__ float geglu(float a, float b) {
  const float K = -2.3022082f;  // -2*sqrt(2/pi)*log2(e)
  const float K3 = K * 0.044715f;
  float p = fmaf(a * a, K3, K);
  float t = fminf(a * p, 126.f);  // keeps 1+2^t finite; the sigmoid is ~1e-38 there
  float e;
  asm("ex2.approx.ftz.f32 %0, %1;" : "=f"(e) : "f"(t));
  float d = e + 1.f;
  float r0 = __int_as_float(0x7EF477D1 - __float_as_int(d));  // 1/d to ~9%
  float e0 = fmaf(-d, r0, 1.f);
  float r1 = fmaf(r0, fmaf(e0, e0, e0), r0);                   // ~1e-3
  float e1 = fmaf(-d, r1, 1.f);
  float r2 = fmaf(r1, e1, r1);                                 // ~5e-7
  return (a * b) * r2;
