// GEGLU: out[r, j] = gelu_tanh(x[r, j]) * x[r, INNER + j], fp32, rows of 2*INNER.
// One fused one-shot launch. Each thread handles 8 consecutive outputs: two 256-bit loads
// (gate half, linear half) and one 256-bit store with an L2 evict_last policy.
// gelu_tanh(a) = 0.5*a*(1+tanh(u)) = a * sigmoid(2u), u = sqrt(2/pi)*(a + 0.044715 a^3).
// Load policy by size (shape-only dispatch): up to EF_MAX_ROWS rows the input loads carry
// L2::evict_first, so read misses evict our own clean input lines instead of the harness
// flush's dirty lines. Above that the outputs overflow the L2 dirty capacity anyway.
// The evict_last policy is the constant CUTLASS encoding (EVICT_LAST), so no createpolicy
// instruction sits between the loads and the stores.
#include <cuda_runtime.h>
#include <stdint.h>

#define INNER 5120
#define THREADS 128
#define CTAS_PER_ROW (INNER / (THREADS * 8))  // 5
#define EF_MAX_ROWS 3072
#define EVICT_LAST_POLICY 0x14F0000000000000ull

#define V8 "{%0,%1,%2,%3,%4,%5,%6,%7}"
