template <bool EF>
__device__ __forceinline__ void ld8(const float* p, float* v) {
  if (EF)
    asm volatile("ld.global.nc.L1::no_allocate.L2::evict_first.v8.f32 " V8 ", [%8];" : O8 : "l"(p));
